variables.$fxv#0:
// BowerSecurityEvents: one row per Bower security event, with delivery replays collapsed.
// Bower delivers at least once. Every replay path re-sends the stored queue row, so the
// copies share the collector-stamped (CollectorId, EventId): an ambiguous Logs Ingestion
// acknowledgement (accepted, response lost), a crash before the acknowledgement commit,
// a restored queue backup and a dead-letter replay. A source resend (RELP or TCP syslog
// after a collector restart, a WEC re-read) of a record whose queue row was lost or
// purged gets the same source-computed EventId. `bower archive replay` must go through a collector with
// the original BOWER_COLLECTOR_ID (a collector with another id refuses it), so it keeps
// the same identity too. Labels never change the identity: producers control them.
// The first copy is kept, so a later row (replayed, or sent by a producer that reused an
// EventId) never replaces content that detections already evaluated.
//   BowerFirstIngested  ingestion_time() of the first copy. Detections use it to evaluate
//                       a late event once, when it first arrived.
//   BowerLastIngested   ingestion_time() of the latest copy.
//   BowerCopies         rows that share the identity (1 = no replay).
//   BowerEventTime      the event time Bower sent. Azure Monitor rewrites TimeGenerated
//                       to the receive time when it is more than two days old; the
//                       original survives in RawEnvelope.timeGenerated.
//   BowerTimeRewritten  true when TimeGenerated no longer equals the sent event time.
// Collector health records and synthetic canaries are operational signals, not security
// events: deploy/sentinel/monitoring queries them from BowerSecurity_CL directly.
// The caller's time range still filters TimeGenerated. All copies of an event share
// TimeGenerated unless Azure rewrote it, so a range keeps or drops them together.
// Count events with count() after this function, never dcount() on the raw table:
// dcount() is an estimate.
BowerSecurity_CL
| where EventType !in ("collector_health", "collector_canary")
| extend BowerIngested = ingestion_time()
| summarize arg_min(BowerIngested, *), BowerLastIngested = max(BowerIngested), BowerCopies = count()
    by CollectorId, EventId
| project-rename BowerFirstIngested = BowerIngested
| extend BowerEventTime = coalesce(todatetime(RawEnvelope.timeGenerated), TimeGenerated)
| extend BowerTimeRewritten = BowerEventTime != TimeGenerated

variables.$fxv#1:
// BowerSecurityEventsOfType(eventTypes: dynamic): BowerSecurityEvents for the listed event
// types, for scheduled rules. The first copy is chosen exactly as BowerSecurityEvents
// chooses it: over every row of the identity (CollectorId, EventId), whatever its type,
// so an EventId reused with another event type picks the same winner; only then are the
// winners filtered by type. To stay cheap it collapses only identities that have a row of
// a listed type, and drops the large dynamic columns (RawEnvelope, Attributes, Target,
// Change, Labels, PrivacyDetected) first; BowerEventTime is read from RawEnvelope before.
let identities = BowerSecurity_CL
    | where EventType in (eventTypes)
    | distinct CollectorId, EventId;
// ingestion_time() is read before the join: it is null on a join's output rows.
BowerSecurity_CL
| where EventType !in ("collector_health", "collector_canary")
| extend BowerIngested = ingestion_time(), BowerEventTime = coalesce(todatetime(RawEnvelope.timeGenerated), TimeGenerated)
| project-away RawEnvelope, Attributes, Target, Change, Labels, PrivacyDetected
| join kind=leftsemi identities on CollectorId, EventId
| summarize arg_min(BowerIngested, *), BowerLastIngested = max(BowerIngested), BowerCopies = count()
    by CollectorId, EventId
| where EventType in (eventTypes)
| project-rename BowerFirstIngested = BowerIngested
| extend BowerTimeRewritten = BowerEventTime != TimeGenerated

variables.$fxv#2:
// Bower replay-safe detection: Windows failed network logons (Security 4625 through
// WEF/WEC and the windows-security-logon pack) from one source address.
// Alerts once per (SourceIpAddress, event-time bucket) when the bucket first reaches
// the threshold. Replayed rows never change the count; late events are counted in the
// run that first sees them. See docs/production-readiness/02-replay-safe-detections.md.
// The main.bicep parameters replace the next seven values; keep them on one line each.
let threshold = 10;
let bucketSize = 10m;
let settleDelay = 5m;
let frequency = 5m;
let catchUp = 60m;
let maxDelay = 360m;
// Runs between retries of a missed crossing: a run's alerts must be queryable in
// SecurityAlert by the run that many runs later (alertVisibilityRuns in main.bicep).
let retrySpacing = 2;
// Detection keys are scoped per deployment (detectionKeyScope in main.bicep), so two
// deployments in one workspace never suppress each other's alerts.
let ruleKey = "bower-wec-brute-force:default";
// In a scheduled run now() is the end of the run's query window. Windows sit on a fixed
// grid of `frequency`, so a redeploy or re-enable that moves the schedule cannot create
// partly overlapping windows.
let windowEnd = bin(now() - settleDelay, frequency);
let catchUpStart = windowEnd - catchUp;
let horizon = bin(catchUpStart - maxDelay, bucketSize);
let alerted = SecurityAlert
    | where ProviderName == "ASI Scheduled Alerts"
    | extend BowerDetectionKey = tostring(todynamic(tostring(todynamic(ExtendedProperties)["Custom Details"])).BowerDetectionKey[0])
    | where BowerDetectionKey startswith strcat(ruleKey, "|")
    | distinct BowerDetectionKey;
let candidates = materialize(BowerSecurityEventsOfType(dynamic(["authentication_failure"]))
    | where EventType == "authentication_failure" and ApplicationName == "windows-security"
    | where isnotempty(SourceIpAddress)
    | where BowerEventTime >= horizon and BowerFirstIngested < windowEnd
    | where BowerFirstIngested - BowerEventTime <= maxDelay
    | extend BucketStart = bin(BowerEventTime, bucketSize));
// Rank only buckets that reach the threshold: the ranking and every aggregate below see
// exactly the same rows per bucket as ranking all buckets, and a bucket below the
// threshold is dropped by `DistinctEvents >= threshold` either way.
let crossedBuckets = candidates
    | summarize BucketEvents = count() by SourceIpAddress, BucketStart
    | where BucketEvents >= threshold
    | project SourceIpAddress, BucketStart;
candidates
| join kind=inner crossedBuckets on SourceIpAddress, BucketStart
| sort by SourceIpAddress asc, BucketStart asc, BowerFirstIngested asc, CollectorId asc, EventId asc
| extend Rank = row_number(1, prev(SourceIpAddress) != SourceIpAddress or prev(BucketStart) != BucketStart)
| summarize CrossedAt = minif(BowerFirstIngested, Rank == threshold), DistinctEvents = count(),
    ReplayedRows = sum(BowerCopies - 1), LateEvents = countif(BowerFirstIngested - BowerEventTime > settleDelay + frequency),
    MaxDeliveryDelay = max(BowerFirstIngested - BowerEventTime), Collectors = make_set(CollectorId, 10),
    TargetAccounts = make_set(ActorUsername, 20), FirstEvent = min(BowerEventTime), LastEvent = max(BowerEventTime)
    by SourceIpAddress, BucketStart
| where DistinctEvents >= threshold
| where CrossedAt >= catchUpStart and CrossedAt < windowEnd
// Slot 0 is this run's own window; runs tile it. A crossing missed there (skipped run,
// late-queryable row) is retried every retrySpacing runs only: a run's alerts have
// TimeGenerated after its window end, so they are outside the next run's look-back.
| extend Slot = toint((windowEnd - CrossedAt) / frequency)
| where Slot == 0 or (Slot >= retrySpacing and Slot % retrySpacing == 0)
| extend BowerDetectionKey = strcat(ruleKey, "|", SourceIpAddress, "|", tostring(BucketStart))
| where BowerDetectionKey !in (alerted)
| extend EvaluationPath = iff(Slot == 0, "owned-window", strcat("catch-up-", Slot)), EvaluatedAt = now()
| project BowerDetectionKey, SourceIpAddress, BucketStart, DistinctEvents, CrossedAt, EvaluationPath, EvaluatedAt,
    ReplayedRows, LateEvents, MaxDeliveryDelay, Collectors, TargetAccounts, FirstEvent, LastEvent

